-- Prevent writes and reveals on idle anonymous sessions.
create or replace function public.heartbeat_anonymous_session(target_session uuid) returns void language plpgsql security definer set search_path='' as $$ begin update public.anonymous_sessions set last_seen_at=now() where id=target_session and status='active' and auth.uid() in(user_a,user_b); end; $$;
create or replace function public.request_anonymous_reveal(target_session uuid) returns boolean language plpgsql security definer set search_path='' as $$ declare ready boolean; begin update public.anonymous_sessions set last_seen_at=now(),reveal_a=case when user_a=auth.uid() then true else reveal_a end,reveal_b=case when user_b=auth.uid() then true else reveal_b end where id=target_session and status='active' and auth.uid() in(user_a,user_b); if not found then raise exception 'Session unavailable'; end if; select reveal_a and reveal_b into ready from public.anonymous_sessions where id=target_session; return ready; end; $$;
